import random, itertools, time
n1=n2=11
N=n1+n2
all_edges=[(i,n1+j) for i in range(n1) for j in range(n2)]

def has_short_cycle_after(adj,u,v):
    # adding edge u-v creates cycle length L iff path length L-1 between u,v before for L<=6. In bipartite path odd lengths 1,3,5 relevant; edge not exist, so path length 3 -> C4, length5 -> C6.
    # BFS up to 5 from u to v in current adj
    frontier={u}
    seen={u}
    for d in range(1,6):
        new=set()
        for x in frontier:
            for y in adj[x]:
                if y not in seen:
                    new.add(y)
                    seen.add(y)
        frontier=new
        if v in frontier and d in (3,5):
            return True
    return False

def greedy(order=None):
    adj=[set() for _ in range(N)]
    edges=[]
    if order is None:
        order=all_edges[:]
        random.shuffle(order)
    for u,v in order:
        if not has_short_cycle_after(adj,u,v):
            adj[u].add(v); adj[v].add(u); edges.append((u,v))
            if len(edges)>=27:
                return edges, adj
    return edges,adj

