# count cycles length 4,6
def count_cycles_len(k):
    count=0
    cycles=set()
    for start in range(N):
        def dfs(path):
            nonlocal count
            if len(path)==k:
                if start in adj[path[-1]]:
                    cyc=path[:]
                    # canonical rotation/reversal
                    rots=[]
                    for arr in (cyc, list(reversed(cyc))):
                        for i in range(k):
                            rots.append(tuple(arr[i:]+arr[:i]))
                    cycles.add(min(rots))
                return
            for nb in adj[path[-1]]:
                if nb==start: continue
                if nb in path: continue
                path.append(nb); dfs(path); path.pop()
        dfs([start])
    return len(cycles)
